 function nativeHistory(){const binding=query('SELECT * FROM xiaozhi_pi_session_bindings WHERE conversation_id=?',[row.session_id])[0];assert(binding);const file=path.resolve(data,'xiaozhi-pi',binding.session_file);assert(file.startsWith(path.resolve(data,'xiaozhi-pi')+path.sep));const raw=fs.readFileSync(file,'utf8');return{file,raw,entries:raw.split('\n').filter(Boolean).map(line=>JSON.parse(line))};}
 function nativeReads(){return nativeHistory().entries.flatMap(entry=>{const m=entry.message;if(m?.role!=='toolResult'||m.toolName!=='education_read_question')return[];return(m.content||[]).filter(p=>p.type==='text').flatMap(p=>{try{return[JSON.parse(p.text)];}catch{return[];}});});}
 async function readBoth(){await navigate('ask');await until(async()=>!await page().getByTestId('office-prompt-input').isDisabled());const n=(await snapshot()).projection.turns.length;await page().getByTestId('office-prompt-input').fill('实际使用education_search_questions和education_read_question分别读取本地物理题“小灯泡”和数学题“x + 2 = 5”（先用关键词分别检索取得本轮别名与version）。不重新读取资料或图片，不创建任何题或文件。只整理读到的关键条件，明确列出“不更换实验器材”、两行电压/电流表数据、图14量程接线与图15刻度、(2)全部选项，以及数学来源答案x。不得猜测物理答案；注明物理答案缺失、数学答案尚未独立验证。');await page().getByTestId('office-prompt-input').press('Enter');assert.equal(await page().getByTestId('office-prompt-input').inputValue(),'');await until(async()=>{const s=await snapshot();return s.projection.turns.length>n&&!s.running;},180000);const turn=(await snapshot()).projection.turns.at(-1);assert.equal(turn.status,'completed');const text=turn.items.filter(x=>x.role==='assistant').map(x=>x.text||'').join('');assert(text.includes('不更换'));assert(text.includes('0.16')&&text.includes('0.26'));assert(text.includes('3'));return turn;}
 await readBoth();let reads=nativeReads();
 for(const[version,projection,answerOrigin]of[[physicalEffect.saved.version,physicalProjection,'missing'],[effect.saved.version,controlProjection,'source']]){const hits=reads.filter(r=>r.version===version&&r.success);assert(hits.length);assert(hits.every(r=>r.contextComplete&&r.teacherConfirmationKnown&&r.answerVerified===false&&r.originalImagesIncluded===false));assert.deepEqual(hits.at(-1).question.context,projection);assert.equal(hits.at(-1).question.answerOrigin,answerOrigin);assert(hits.every(r=>!JSON.stringify(r).includes('data:image')&&!JSON.stringify(r).includes('asset_')&&!JSON.stringify(r).includes(data)));}
 assert.equal(JSON.stringify(questions()),facts);assert.equal(JSON.stringify(ledgers()),ledger);check('Actual DeepSeek/Pi reads all six current physical conditions and source arithmetic sections without images/private paths, invented answers or fact writes');
 const sourceButtons=page().getByTestId('pi-question-source-open').filter({hasText:'跨页算术来源对照'});let sourceButton;
 for(const button of await sourceButtons.all())if(await button.isVisible()){sourceButton=button;break;}assert(sourceButton);await sourceButton.click();
 const dialog=page().getByTestId('pi-question-source-dialog');await dialog.waitFor();assert((await dialog.getByTestId('question-answer-origin').innerText()).includes('原资料提供'));assert((await dialog.getByTestId('question-analysis-origin').innerText()).includes('教师补充'));assert((await dialog.getByTestId('question-answer-verification').innerText()).includes('尚未独立核对正确性'));assert(!(await dialog.innerText()).includes('标准答案'));await capture('pi-source-answer',dialog,'pi-question-source-close');await dialog.getByTestId('pi-question-source-close').click();await dialog.waitFor({state:'hidden'});check('Actual Pi citation opens the shared readonly answer evidence in the accessible source dialog, without claiming correctness');
 const historyBefore=nativeHistory(),compactionsBefore=historyBefore.entries.filter(x=>x.type==='compaction').length,turnsBefore=(await snapshot()).projection.turns.length;
 if(!await page().getByTestId('pi-compact').isVisible())await page().getByTestId('pi-task-details-expand').click();await page().getByTestId('pi-compact').click();await until(async()=>{const s=await snapshot();return s.projection.turns.length>turnsBefore&&!s.running;},180000);const compactState=await snapshot();assert.equal(compactState.projection.turns.at(-1).status,'completed');const compactHistory=nativeHistory();assert(compactHistory.raw.startsWith(historyBefore.raw));assert.equal(compactHistory.entries.filter(x=>x.type==='compaction').length,compactionsBefore+1);assert.equal(JSON.stringify(questions()),facts);assert.equal(JSON.stringify(ledgers()),ledger);check('Actual native Pi summary appends immutable history and preserves original approvals, document versions and incomplete answer status');
 const beforeColdReads=nativeReads().length;await restart();assert.equal(JSON.stringify(questions()),facts);assert.equal(JSON.stringify(ledgers()),ledger);await readBoth();reads=nativeReads();assert(reads.length>=beforeColdReads+2);assert(nativeHistory().entries.some(x=>x.type==='compaction'));assert(reads.slice(beforeColdReads).some(r=>r.version===physicalEffect.saved.version&&r.contextComplete));assert(reads.slice(beforeColdReads).some(r=>r.version===effect.saved.version&&r.contextComplete));assert.equal(JSON.stringify(questions()),facts);assert.equal(JSON.stringify(ledgers()),ledger);assert.equal((await snapshot()).limitsEnforced,false);check('Cold continuation after actual compaction rediscoveries both current question versions; no stale alias, approval replay or run budget');
 const nativeProposals=nativeHistory().entries.flatMap(e=>(e.message?.role==='assistant'?e.message.content:[])||[]).filter(p=>p.type==='toolCall'&&p.name==='education_propose_original_question');const physicalCall=nativeProposals.find(p=>p.id===physicalPayload.callId);assert(physicalCall);if(single){assert.equal(physicalCall.arguments.page,6);assert.deepEqual(physicalCall.arguments.box,[0,0,1,1]);assert.equal(physicalCall.arguments.regions,undefined);}else assert.equal(physicalCall.arguments.regions.length,2);check('Native Pi history proves the actual requested page/box or regions input, not a test-side route substitution');
 report.result={nativeProposals,singleRegionToolInput:single,physical:{sourceSha256:sample.sha256,questionId:physicalQuestion.id,document:physicalDocument},control:{sourceSha256:sha(controlBytes),questionId:controlQuestion.id,document:controlDocument},formalQuestions:2,sourceImages:view.images.map(x=>({role:x.role,page:x.image.page,sha256:x.image.sha256,assetId:x.image.assetId})),sessionId:row.session_id,runId:row.run_id,answerTruth:'Teacher-authored arithmetic source control only; scan independent answers remain missing',nativeReads:reads,compactionCount:nativeHistory().entries.filter(x=>x.type==='compaction').length};fs.writeFileSync(path.join(output,'readback.json'),JSON.stringify(report.result,null,2));
